import { Logo } from "../components/Logo";
import { useEffect } from "react";
import { ScribbrEnv } from "@cgs/types";
import { Trans, useTranslation } from "react-i18next";
import { sendMessage } from "../common/messaging";
import { getScribbrHost } from "@cgs/utils";
import { DOMAIN } from "../common/constants";
import { GoogleDocsAccountSettings } from "./GoogleDocsAccountSettings";
import { SettingsSection } from "./SettingsSection";
import { privacyPolicyUrl } from "../common/types";

export const GoogleDocsSettingsPage = ({ env }: { env: ScribbrEnv }) => {
  const { t } = useTranslation();

  useEffect(() => {
    (async () => {
      await sendMessage({ type: "fetchUserInfo" });
    })();
  }, []);

  return (
    <div>
      <header className="flex border-b p-5">
        <a href={getScribbrHost(DOMAIN, env)} target="_blank" rel="noreferrer">
          <Logo className="h-6" />
        </a>
      </header>
      <div className="container mx-auto max-w-lg">
        <div className="space-y-9 py-9">
          <h1 className="heading-1 px-5">{t("settingsPage.googleDocs.title")}</h1>
          <SettingsSection>
            <div className="flex flex-col gap-5">
              <div className="whitespace-pre-line">
                <Trans
                  i18nKey="settingsPage.googleDocs.description"
                  components={{
                    a: (
                      <a
                        href={privacyPolicyUrl["en-US"]}
                        target="_blank"
                        rel="noreferrer"
                        className="text-blue-9"
                      />
                    ),
                  }}
                />
              </div>
              <GoogleDocsAccountSettings />
            </div>
          </SettingsSection>
        </div>
      </div>
    </div>
  );
};
