import { useTranslation } from "react-i18next";
import { useCallback, useEffect, useState } from "react";
import { Button } from "@cgs/ui";
import { useSettingsContext } from "./SettingsContext";
import { sendMessage } from "../common/messaging";
import { getAuthToken } from "../google/auth";

export const GoogleDocsAccountSettings = () => {
  const { t } = useTranslation();
  const [isAccountLinked, setIsAccountLinked] = useState(false);
  const { saveSettings, settings } = useSettingsContext();

  const linkAccount = useCallback(async () => {
    const { token } = await getAuthToken({ interactive: true });

    if (token != null) {
      saveSettings({ googleDocsToken: token });
      setIsAccountLinked(true);
      await sendMessage({
        type: "logEvent",
        event: {
          name: "Citation Generator Browser Extension Google Account linked",
          data: {
            extension_language: "en-US",
          },
        },
      });

      const currentTab = await chrome.tabs.getCurrent();
      if (currentTab != null && currentTab.id != null) {
        chrome.tabs.remove(currentTab.id);
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const unlinkAccount = useCallback(async () => {
    try {
      if (settings.googleDocsToken != null) {
        await fetch(`https://accounts.google.com/o/oauth2/revoke?token=${settings.googleDocsToken}`);
        await chrome.identity.removeCachedAuthToken({ token: settings.googleDocsToken });
        saveSettings({ googleDocsToken: undefined });
        setIsAccountLinked(false);
        await sendMessage({
          type: "logEvent",
          event: {
            name: "Citation Generator Browser Extension Google Account unlinked",
            data: {
              extension_language: "en-US",
            },
          },
        });
      }
    } catch (e) {
      // ignore
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (settings.googleDocsToken != null) {
      setIsAccountLinked(true);
    }
  }, [settings.googleDocsToken]);

  return (
    <div className="flex flex-col gap-5">
      <Button variant="outline" onClick={isAccountLinked ? unlinkAccount : linkAccount}>
        {isAccountLinked ? t("docsWidget.login.unlinkAccount") : t("docsWidget.login.linkAccount")}
      </Button>
    </div>
  );
};
