import i18n from "i18next";
import { initReactI18next } from "react-i18next";
import enUs from "../locales/en-US.json";
import nlNL from "../locales/nl-NL.json";
import enUsUi from "@cgs/ui/locales/en-US.json";
import nlNLUi from "@cgs/ui/locales/nl-NL.json";

i18n.use(initReactI18next).init({
  resources: {
    "en-US": { extension: enUs, ui: enUsUi },
    "nl-NL": { extension: nlNL, ui: nlNLUi },
  },
  lng: "en-US",
  fallbackLng: {
    default: ["en-US"],
  },
  defaultNS: "extension",
  ns: ["extension", "ui"],
  fallbackNS: "ui",
});

export default i18n;
