import {
  BibStyle,
  CitationStyleOptions,
  Domain,
  Locale,
  Range,
  ScribbrEnv,
  SourceType,
  SourceTypes,
  houstonSubdomains,
  subdomains,
} from "@cgs/types";

export const escapeRegExp = (text: string): string => text.replace(/[\\^$.*+?()[\]{}|]/g, "\\$&");

export function unwrapFirstItem<T>(arr: Array<T> | T): T | undefined {
  return ([] as Array<T>).concat(arr)[0];
}

export function wrapArray<T>(arr?: Array<T> | ReadonlyArray<T> | T): Array<T> {
  const result: Array<T> = [];
  return arr == undefined ? result : result.concat(arr);
}

export const isRange = (value: unknown): value is Range<unknown> => {
  return value !== null && typeof value === "object" && "start" in value && "end" in value;
};

export const urlAddProtocol = (url: string, defaultProtocol = "https") => {
  let newUrl = url.trim();

  if (!url.match(/^https?:\/\//)) {
    newUrl = `${defaultProtocol}://${newUrl}`;
  }

  return newUrl;
};

export const urlRemoveProtocol = (url: string) => {
  return url
    .trim()
    .replace(/(^\w+:|^)\/\//, "")
    .replace(/\/$/, "");
};

export function urlGetOrigin(url: string) {
  try {
    const parsedUrl = new URL(url);

    return parsedUrl.origin;
  } catch (_error) {
    return url;
  }
}

export const getScribbrHost = (domain: Domain, env: ScribbrEnv) => {
  return `https://${subdomains[env]}.scribbr.${domain}`;
};

export function isSourceType(value: string | undefined): value is SourceType {
  return value != undefined && SourceTypes.includes(value as SourceType);
}

export const getHoustonHost = (domain: Domain, env: ScribbrEnv) => {
  return `https://${houstonSubdomains[env]}.scribbr.${domain}`;
};

export const camelCase = (s: string) => {
  let output = s.charAt(0).toLocaleLowerCase() + s.slice(1);
  output = output.replace(/[-_]./g, (x) => {
    if (!x[1]) {
      throw new Error(`Error in camelcasing: ${x}`);
    }
    return x[1].toUpperCase();
  });
  return output;
};

export function capitalize(word: string, locale?: Locale): string {
  if (!word.length) {
    return word;
  }
  const firstLetter = word.substring(0, 1);
  return word.replace(firstLetter, firstLetter.toLocaleUpperCase(locale));
}

export const MAX_WORKS = 50;

export function getAnnotationStyle(
  citationStyleOptions: CitationStyleOptions,
  isFirstParagraph: boolean,
  hasMultipleParagraphs: boolean,
): BibStyle {
  const { annotationStyle } = citationStyleOptions;

  if (isFirstParagraph && !hasMultipleParagraphs && annotationStyle.single) {
    return annotationStyle.single;
  }

  if (isFirstParagraph && hasMultipleParagraphs && annotationStyle.first) {
    return annotationStyle.first;
  }

  return annotationStyle.default;
}

export function splitParagraphs(text: string): Array<string> {
  return cleanupNewLines(text).split(/\n/);
}

export function cleanupNewLines(text: string) {
  // strip whitespace, and double new lines
  return text.replace(/(?!\n)\s\s+/g, "").replace(/\n+/g, "\n");
}

/* eslint-disable @typescript-eslint/no-empty-object-type */
export function hasOwnProperty<X extends {}, Y extends PropertyKey>(
  obj: X,
  prop: Y,
): obj is X & Record<Y, unknown> {
  return obj.hasOwnProperty(prop);
}
/* eslint-enable @typescript-eslint/no-empty-object-type */

type ValueOf<T> = T[keyof T];
type NonEmptyArray<T> = [T, ...T[]];
type MustInclude<T, U extends T[]> = [T] extends [ValueOf<U>] ? U : never;
export const enumerate =
  <T>() =>
  <U extends NonEmptyArray<T>>(...elements: MustInclude<T, U>) =>
    elements;

