export async function getAuthToken({ interactive }: { interactive: boolean }) {
  const authUrl = "https://accounts.google.com/o/oauth2/auth";
  const redirectUrl = chrome.identity.getRedirectURL();

  const clientId = chrome.runtime.getManifest().oauth2?.client_id;

  if (!clientId) {
    throw new Error("No client_id in manifest.json");
  }

  const authParams = {
    client_id: clientId,
    redirect_uri: redirectUrl,
    response_type: "token",
    scope: "https://www.googleapis.com/auth/documents",
  };

  const url = `${authUrl}?${new URLSearchParams(authParams)}`;

  const response = await chrome.identity.launchWebAuthFlow({
    url,
    interactive,
  });

  if (response == null) {
    throw new Error("No response from Google");
  }

  const responseUrl = new URL(response);
  const responseParams = new URLSearchParams(responseUrl.hash.substring(1));

  const token = responseParams.get("access_token");

  if (token == null) {
    throw new Error("No token in response from Google");
  }

  return { token };
}
